; @mideas:block id=runtime.screens.load_screen_terminal_velocity_screen_locity_blank.loader kind=routine owner=screens roots=load_screen_terminal_velocity_screen_locity_blank
load_screen_terminal_velocity_screen_locity_blank:
    ; Load Terminal Velocity Screen screen (fast direct port access)
    ld a, 1
    ld (current_screen_engine), a
    ld a, #FF
    ld (autocontrol_screen_id), a
    ; Set VDP colors FIRST (before loading screen data)
    ld a, 1           ; Background color
    ld b, 1       ; Border color
    call set_screen_colors
    ; Initialize character 0 (empty cells) with background color
    ld a, 1           ; Background color for char 0
    call init_char0_color
    ; Build mutable runtime screen background map in RAM
    ld hl, SCREEN_TERMINAL_VELOCITY_SCREEN_0_LAYOUT
    ld de, runtime_screen_layout
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir
    ld hl, SCREEN_TERMINAL_VELOCITY_SCREEN_0_EFFECTS_LAYOUT
    ld de, runtime_effects_layout
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, BEHAVIOR_TERMINAL_VELOCITY_SCREEN_0_DATA
    ld de, runtime_behavior_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, SCREEN_TERMINAL_VELOCITY_SCREEN_0_INTERACTION_TYPE_MAP
    ld de, runtime_interaction_type_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, SCREEN_TERMINAL_VELOCITY_SCREEN_0_INTERACTION_VALUE_MAP
    ld de, runtime_interaction_value_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, SCREEN_TERMINAL_VELOCITY_SCREEN_0_INTERACTION_TARGET_MAP
    ld de, runtime_interaction_target_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld a, 0
    ld (current_effect_zone_count), a
    or a
    jr z, .load_terminal_velocity_screen_locity_blank_zones_done
    ld hl, SCREEN_TERMINAL_VELOCITY_SCREEN_0_EFFECT_ZONE_TABLE
    ld de, runtime_effect_zone_table
    ld bc, 0
    ldir
.load_terminal_velocity_screen_locity_blank_zones_done:
    ; Transition->WorldLink reveal mode prepares runtime_screen_layout first,
    ; then GameFlow reveals it by raster after the world loader returns.
    ld a, (gameflow_reveal_world_after_load)
    or a
    jr nz, load_screen_terminal_velocity_screen_locity_blank_skip_vram_copy
    ; Now load screen layout (full 32x24) from runtime RAM buffer
    ld hl, runtime_screen_layout
    ld de, NAMETBL
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    call FAST_LDIRVM           ; Fast VRAM write (direct port access)
load_screen_terminal_velocity_screen_locity_blank_skip_vram_copy:
    ld a, 0
    ld (current_screen_anim_group_count), a
    ld a, 0
    ld (current_screen_entity_count), a
    ld a, 1
